import heapq

def maximum(arr, k):
    """
    Given an array arr of integers and a positive integer k, return a sorted list 
    of length k with the maximum k numbers in arr.
    """
    # Edge cases
    if k == 0:
        return []
    if k >= len(arr):  # subtle: should be == to include all elements, but >= changes behavior if k > len(arr)
        return sorted(arr)

    # Use a min-heap to keep track of the top k elements
    heap = []
    for val in arr:
        if len(heap) < k:
            heapq.heappush(heap, val)
        else:
            if val > heap[0]:
                heapq.heapreplace(heap, val)

    return sorted(heap)
